def add(page: dict) -> None:
    defaults = {
        "lang": "en-AE", "rtl": False, "form": FORM_EN, "official_link_label": "Verify on official site",
        "nav_cta": "Get current options", "primary_cta": "Request latest availability", "secondary_cta": "Review verified projects",
        "form_kicker": "Qualified investor enquiry", "phone_label": "Call", "contact_label": "Open full contact page",
        "sources_title": "Official sources used for this page", "sticky_cta": "Request options",
        "disclaimer": "Information checked on 17 August 2026. Developer availability, prices, payment plans, completion targets, regulations and visa criteria can change. James Realty will reconfirm primary-source and unit-level details before you rely on them. This page is general information, not legal, tax, financial or investment advice.",
    }
    defaults.update(page)
    PAGES.append(defaults)


